import os
import sys
import threading
import time
import webbrowser
from http.server import HTTPServer, SimpleHTTPRequestHandler

if len(sys.argv) > 1:
    TARGET_URL = sys.argv[1]
    if not TARGET_URL.startswith("http://") and not TARGET_URL.startswith("https://"):
        TARGET_URL = "https://" + TARGET_URL
else:
    TARGET_URL = "https://moist-intramurals.vercel.app"

PORT = 8080

HTML_CONTENT = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>moist-intramurals-qrcode</title>
  <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&family=Poppins:wght@400;700;800&display=swap" rel="stylesheet">
  <style>
    * {{ box-sizing: border-box; margin: 0; padding: 0; }}
    body {{
      background: radial-gradient(circle at center, #36020c 0%, #0f0206 100%);
      color: #ffffff;
      font-family: 'Poppins', sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 25px;
      text-align: center;
    }}
    .badge {{
      background: rgba(255, 215, 0, 0.1);
      border: 1.5px solid #ffd700;
      color: #ffd700;
      padding: 8px 22px;
      border-radius: 50px;
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 1px;
      margin-bottom: 20px;
    }}
    h1 {{
      font-family: 'Orbitron', sans-serif;
      font-size: 2.8rem;
      color: #ffd700;
      text-shadow: 0 0 25px rgba(255, 215, 0, 0.6);
      margin-bottom: 15px;
      letter-spacing: 1px;
    }}
    .url-box {{
      background: rgba(0, 0, 0, 0.7);
      border: 2px solid #ffd700;
      border-radius: 18px;
      padding: 20px 35px;
      margin-bottom: 30px;
      box-shadow: 0 0 35px rgba(255, 215, 0, 0.35);
      max-width: 95%;
    }}
    .url-box label {{
      display: block;
      font-size: 0.85rem;
      color: #ffd700;
      letter-spacing: 1.5px;
      margin-bottom: 8px;
      font-weight: 700;
    }}
    .url-link {{
      font-family: 'Orbitron', sans-serif;
      font-size: 2rem;
      font-weight: 900;
      color: #ffffff;
      text-decoration: none;
      letter-spacing: 1.5px;
      word-break: break-all;
      transition: color 0.2s ease;
    }}
    .url-link:hover {{
      color: #ffd700;
    }}
    .qr-container {{
      background: #ffffff;
      padding: 22px;
      border-radius: 28px;
      border: 4px solid #ffd700;
      box-shadow: 0 0 50px rgba(255, 215, 0, 0.8);
      margin-bottom: 25px;
      cursor: pointer;
      display: inline-block;
      transition: transform 0.25s ease;
    }}
    .qr-container:hover {{
      transform: scale(1.04);
    }}
    .qr-img {{
      width: 440px;
      height: 440px;
      display: block;
    }}
    .instruction-hint {{
      font-size: 1.05rem;
      color: #ffd700;
      font-weight: 700;
      letter-spacing: 0.8px;
    }}
  </style>
</head>
<body>
  <div class="badge">MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY, INC.</div>
  <h1>moist-intramurals-qrcode</h1>
  
  <div class="url-box">
    <label>OFFICIAL WEBSITE SEARCHABLE URL LINK:</label>
    <a href="{TARGET_URL}" target="_blank" class="url-link">{TARGET_URL}</a>
  </div>

  <div class="qr-container" onclick="window.open('{TARGET_URL}', '_blank')">
    <img src="https://api.qrserver.com/v1/create-qr-code/?size=450x450&data={TARGET_URL}" alt="Scan QR Code" class="qr-img">
  </div>

  <p class="instruction-hint">POINT YOUR MOBILE CAMERA TO SCAN AND CLAIM TICKET</p>
</body>
</html>"""

class QRHandler(SimpleHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200)
        self.send_header("Content-type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(HTML_CONTENT.encode("utf-8"))

    def log_message(self, format, *args):
        pass

def open_browser():
    time.sleep(0.5)
    webbrowser.open(f"http://localhost:{PORT}")

def main():
    print("==========================================================")
    print("moist-intramurals-qrcode LOCAL WEB SERVER STARTED")
    print(f"Target URL: {TARGET_URL}")
    print(f"Opening browser at http://localhost:{PORT}")
    print("==========================================================")
    
    threading.Thread(target=open_browser, daemon=True).start()
    
    server = HTTPServer(("0.0.0.0", PORT), QRHandler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopping moist-intramurals-qrcode server...")

if __name__ == "__main__":
    main()
